const raw = $input.first().json.message;
let payload;
try {
  payload = typeof raw === 'string' ? JSON.parse(raw) : raw;
} catch (error) {
  throw new Error('Payload MQTT não é JSON válido');
}

const deviceId = String(payload.device_id || '').trim();
const temp = Number(payload.temp);
const umid = Number(payload.umid);
const ic = payload.ic === undefined || payload.ic === null ? null : Number(payload.ic);

if (!/^[a-zA-Z0-9_-]{1,64}$/.test(deviceId)) throw new Error('device_id inválido');
if (!Number.isFinite(temp) || temp < -40 || temp > 80) throw new Error('temperatura inválida');
if (!Number.isFinite(umid) || umid < 0 || umid > 100) throw new Error('umidade inválida');
if (ic !== null && !Number.isFinite(ic)) throw new Error('índice de calor inválido');

return [{ json: { device_id: deviceId, temp, umid, ic } }];

const { execFileSync } = require('child_process');

const envValue = (name) => {
  try {
    return execFileSync('printenv', [name], { timeout: 2000 }).toString().trim();
  } catch {
    return '';
  }
};

const server = envValue('ZABBIX_SERVER');
const port = envValue('ZABBIX_PORT') || '10051';
const host = envValue('ZABBIX_HOST_NAME');
if (!server || !host) throw new Error('ZABBIX_SERVER/ZABBIX_HOST_NAME não configurados');

const data = $input.first().json;
const items = [
  ['temperatura', data.temp],
  ['umidade', data.umid],
  ['indice_calor', data.ic],
];

const errors = [];
for (const [key, value] of items) {
  if (value === null || value === undefined) continue;
  try {
    execFileSync('/usr/bin/zabbix_sender', [
      '-z', server, '-p', port, '-s', host, '-k', key, '-o', String(value),
    ], { timeout: 5000 });
  } catch (error) {
    errors.push(`${key}: ${error.message}`);
  }
}

return [{ json: { ...data, zabbix_ok: errors.length === 0, zabbix_errors: errors } }];
